#include <Aevrynd/ReplicationRuntime3D.h>
#include <cmath>
#include <iostream>
#include <limits>
#include <ranges>
using namespace Aevrynd;
static double X(GlobalPosition3D p){return double(p.chunk.x)*32.0+p.offset.x;}
int main(){LoopbackNetworkSettings3D network{};network.maximumEndpoints=3;network.maximumQueuedPackets=8192;network.maximumQueuedBytes=8*1024*1024;network.lossPermille=200;network.duplicatePermille=100;network.reorderPermille=250;network.maximumJitterTicks=3;network.seed=93;LoopbackNetworkTransport3D transport(network);for(auto endpoint:{NetworkEndpoint3D{1},NetworkEndpoint3D{2},NetworkEndpoint3D{3}})if(!transport.RegisterEndpoint(endpoint))return 1;ReplicationRuntimeSettings3D settings{};settings.maximumInputHistory=512;settings.maximumSnapshotHistory=128;ReplicationServer3D server(transport,{1},77,settings);if(!server.AddClient(1,{2})||!server.AddClient(2,{3},{{1,0,0},{0,0,0}}))return 2;ReplicationClient3D first(transport,{2},{1},77,1,settings),second(transport,{3},{1},77,2,settings);
 for(std::uint64_t tick=1;tick<=2000;++tick){first.SubmitInput(32767,0);second.SubmitInput(-16384,0);first.Tick();second.Tick();transport.AdvanceTo(tick+4);server.Tick();}
 // 停止輸入後繼續交換封包，必須在封包遺失與重排後收斂。
 for(std::uint64_t tick=2001;tick<=2400;++tick){first.Tick();second.Tick();transport.AdvanceTo(tick+4);server.Tick();}
 const auto a=server.Player(1),b=server.Player(2);if(!a||!b)return 3;if(std::abs(X(a->position)-X(first.Predicted().position))>.25||std::abs(X(b->position)-X(second.Predicted().position))>.25){std::cerr<<"convergence failed server="<<X(a->position)<<","<<X(b->position)<<" client="<<X(first.Predicted().position)<<","<<X(second.Predicted().position)<<'\n';return 4;}if(!first.Remote({77,2},.5f)||!second.Remote({77,1},.5f))return 5;const auto ss=server.Stats();if(!ss.fullSnapshots||!ss.deltaSnapshots||!ss.acks||!first.Stats().reconciliations||!second.Stats().reconciliations)return 6;if(first.Stats().historyDrops||second.Stats().historyDrops)return 7;
 // 無損fixture精確驗證重複、過舊與過遠未來輸入拒絕。
 LoopbackNetworkSettings3D cleanSettings{};cleanSettings.maximumEndpoints=2;LoopbackNetworkTransport3D clean(cleanSettings);clean.RegisterEndpoint({10});clean.RegisterEndpoint({11});ReplicationRuntimeSettings3D tight{};tight.maximumInputHistory=4;ReplicationServer3D guarded(clean,{10},99,tight);guarded.AddClient(1,{11});auto send=[&](ReplicationInputCommand3D input){std::vector<std::byte> encoded;if(!EncodeReplicationPacket3D(input,encoded)||!clean.Send({11},{10},encoded))return false;clean.AdvanceTo(clean.Stats().advancedTicks+1);guarded.Tick();return true;};if(!send({99,1,1,1,1,0,0,false})||!send({99,1,1,1,1,0,0,false})||!send({99,1000,2,1,1,0,0,false}))return 8;for(int i=0;i<8;++i)guarded.Tick();if(!send({99,1,3,1,1,0,0,false}))return 9;const auto gs=guarded.Stats();if(!gs.duplicateInputs||!gs.futureInputs||!gs.staleInputs)return 10;
 // 惡意極大sequence不得污染；後續正常sequence仍可接受。
 if(!send({99,guarded.Stats().ticks+1,(std::numeric_limits<std::uint64_t>::max)(),1,1,0,0,false}))return 11;const auto acceptedBefore=guarded.Stats().inputsReceived;if(!send({99,guarded.Stats().ticks+1,4,1,1,0,0,false})||guarded.Stats().inputsReceived!=acceptedBefore+1)return 12;
 // 獨立interest fixture驗證負座標與teleport後不洩漏範圍外entity。
 LoopbackNetworkSettings3D interestNetSettings{};interestNetSettings.maximumEndpoints=3;LoopbackNetworkTransport3D interestNet(interestNetSettings);for(auto e:{NetworkEndpoint3D{20},NetworkEndpoint3D{21},NetworkEndpoint3D{22}})interestNet.RegisterEndpoint(e);ReplicationRuntimeSettings3D interestSettings{};interestSettings.interestLoadRadius=1;interestSettings.interestRetainRadius=2;ReplicationServer3D interestServer(interestNet,{20},101,interestSettings);if(!interestServer.AddClient(1,{21},{{-2,0,-2},{0,0,0}})||!interestServer.AddClient(2,{22},{{100,0,100},{0,0,0}}))return 13;interestNet.AdvanceTo(1);interestServer.Tick();NetworkPacket3D observed;bool foundSnapshot=false;while(interestNet.TryReceive({21},observed)){ReplicationMessage3D decoded;if(DecodeReplicationPacket3D(observed.bytes,decoded))if(auto*s=std::get_if<ReplicationSnapshot3D>(&decoded)){foundSnapshot=true;if(std::ranges::any_of(s->entities,[](const auto&e){return e.id==NetworkEntityId3D{101,2};}))return 14;}}if(!foundSnapshot)return 15;
 if(!interestServer.SetClientPosition(2,{{-2,0,-2},{1,0,1}})){return 16;}interestNet.AdvanceTo(2);interestServer.Tick();bool entered=false;while(interestNet.TryReceive({21},observed)){ReplicationMessage3D decoded;if(DecodeReplicationPacket3D(observed.bytes,decoded))if(auto*s=std::get_if<ReplicationSnapshot3D>(&decoded))entered|=std::ranges::any_of(s->entities,[](const auto&e){return e.id==NetworkEntityId3D{101,2};});}if(!entered)return 17;
 // 合法ACK建立baseline後，future ACK flood不得污染baseline或增加full snapshot。
 NetworkPacket3D ackPacket;std::uint64_t knownSnapshot{};while(clean.TryReceive({11},ackPacket)){ReplicationMessage3D decoded;if(DecodeReplicationPacket3D(ackPacket.bytes,decoded))if(auto*s=std::get_if<ReplicationSnapshot3D>(&decoded))knownSnapshot=(std::max)(knownSnapshot,s->serverTick);}auto transmitAck=[&](std::uint64_t value){std::vector<std::byte> encoded;return EncodeReplicationPacket3D(ReplicationAck3D{99,value,0,1},encoded)&&clean.Send({11},{10},encoded);};if(!knownSnapshot||!transmitAck(knownSnapshot))return 18;clean.AdvanceTo(clean.Stats().advancedTicks+1);guarded.Tick();const auto fullBeforeFlood=guarded.Stats().fullSnapshots;for(int i=0;i<32;++i)if(!transmitAck((std::numeric_limits<std::uint64_t>::max)()-i))return 19;clean.AdvanceTo(clean.Stats().advancedTicks+1);guarded.Tick();if(guarded.Stats().fullSnapshots!=fullBeforeFlood)return 20;
 std::cout<<"ticks="<<ss.ticks<<" full="<<ss.fullSnapshots<<" delta="<<ss.deltaSnapshots<<" acks="<<ss.acks<<" loss="<<transport.Stats().lost<<" reconcile="<<first.Stats().reconciliations+second.Stats().reconciliations<<'\n';return 0;}
